function centavos(value: number): number {
  assert.ok(Number.isFinite(value), "A money value must be finite");
  const result = Math.round((value + Number.EPSILON) * 100);
  assert.ok(Number.isSafeInteger(result), "Unsafe centavo value");
  return result;
}

function exact(actual: number, expected: number, description: string) {
  assert.equal(centavos(actual), centavos(expected), description + ": expected " + expected + ", got " + actual);
}

test("19 independent SSS/PhilHealth/HDMF official-source monthly reference values", () => {
  const monthlyEvidence: unknown[] = [];
  for (const c of workers) {
    const sss = computeSss(c.salary, SOURCE_DATE);
    exact(sss.monthlySalaryCredit, c.msc, c.id + " SSS MSC / circular row " + c.sssRow);
    exact(sss.employee, c.sssEe, c.id + " SSS employee");
    exact(sss.employer, c.sssEr, c.id + " SSS employer");
    exact(sss.employerEC, c.ec, c.id + " SSS EC employer only");
    const ph = computePhilHealth(c.salary, SOURCE_DATE);
    exact(ph.total, c.phPremium, c.id + " PhilHealth premium");
    if (c.phEe !== null && c.phEr !== null) {
      exact(ph.employee, c.phEe, c.id + " PhilHealth EE (even-cent premium)");
      exact(ph.employer, c.phEr, c.id + " PhilHealth ER (even-cent premium)");
    } else {
      // EXPLICIT SOURCE NOT VERIFIED: no manufactured employee/employer oracle.
      assert.equal(c.id === "C07" || c.id === "C14", true);
    }
    const hdmf = computePagIbig(c.salary, SOURCE_DATE);
    exact(hdmf.employee, c.pagEe, c.id + " HDMF employee");
    exact(hdmf.employer, c.pagEr, c.id + " HDMF employer");
    const expected = {
      msc: c.msc, sssEe: c.sssEe, sssEr: c.sssEr, ec: c.ec,
      phPremium: c.phPremium, phEe: c.phEe, phEr: c.phEr,
      hdmfEe: c.pagEe, hdmfEr: c.pagEr,
    };
    const observed = {
      msc: sss.monthlySalaryCredit, sssEe: sss.employee, sssEr: sss.employer,
      ec: sss.employerEC, phPremium: ph.total, phEe: ph.employee,
      phEr: ph.employer, hdmfEe: hdmf.employee, hdmfEr: hdmf.employer,
    };
    const deltaCentavos = Object.fromEntries(Object.entries(expected).map(([key, value]) =>
      [key, value === null ? null : centavos(observed[key as keyof typeof observed]) - centavos(value)],
    ));
    monthlyEvidence.push({
      case: c.id, monthlySalary: c.salary, frequency: "semi-monthly",
      officialTableRow: { sss: c.sssRow, philHealth: "2025 advisory basic-salary band", pagIbig: "Circular 460 section C" },
      sourceStatus: c.phEe === null ? "SOURCE NOT VERIFIED (PH odd-cent EE/ER)" : "source verified",
      expected, observed, deltaCentavos,
    });
  }
  console.log("STATUTORY_COMPARISON_MONTHLY_EVIDENCE " + JSON.stringify(monthlyEvidence));
});

test("BIR monthly and semi-monthly Annex E and annual Table 2: every boundary and bracket", () => {
  assert.equal(taxVectors.length, 33);
  for (const v of taxVectors) {
    const fn = v.frequency === "monthly" ? computeMonthlyWithholdingTax
      : v.frequency === "semi-monthly" ? computeSemiMonthlyWithholdingTax
      : computeAnnualWithholdingTax;
    exact(fn(v.taxable, false, SOURCE_DATE), v.expected,
      v.frequency + " column " + v.row + " " + v.kind + " taxable " + v.taxable);
  }
  // MWE has no supplementary taxable compensation in this narrow illustration.
  exact(computeMonthlyWithholdingTax(16680, true, SOURCE_DATE), 0, "MWE minimum basic monthly exempt");
  exact(computeSemiMonthlyWithholdingTax(8340, true, SOURCE_DATE), 0, "MWE minimum basic semi-monthly exempt");
});

test("DOLE basic/12 and BIR one shared 90,000 benefit pool: under and over", () => {
  // 300,000 annual earned BASIC -> 25,000 13th; this is an entitlement,
  // distinct from 50,000 and 80,000 other-benefit payments.
  const input = {
    releasedBasicYtd: 300000, historicalBasicYtd: 0, unpaidBasicSalary: 0,
    thirteenthPaidYtd: 0, grossCompensationYtd: 300000,
    statutoryContributionsYtd: 0, taxWithheldYtd: 0,
    mwe: false, leaveMonetizationPay: 0, separationPay: 0,
    retirementPay: 0, otherBenefits: 0, loanDeductions: 0,
  };
  const final = computeFinalPay(input);
  exact(final.thirteenthEntitlement, 25000, "DOLE 1/12 x annual basic");
  const under = annualize({
    grossCompensation: 375000, thirteenthMonth: 25000, otherBenefits: 50000,
    statutoryContributions: 0, taxWithheld: 0, mwe: false,
  });
  exact(under.benefitPool, 75000, "under combined pool");
  exact(under.exemptBenefitPool, 75000, "under exempt");
  exact(under.taxableBenefitPool, 0, "under excess");
  exact(under.taxableIncome, 300000, "under annual taxable");
  exact(under.taxDue, 7500, "under annual BIR column 2");
  const over = annualize({
    grossCompensation: 405000, thirteenthMonth: 25000, otherBenefits: 80000,
    statutoryContributions: 0, taxWithheld: 0, mwe: false,
  });
  exact(over.benefitPool, 105000, "over combined pool");
  exact(over.exemptBenefitPool, 90000, "over exempt");
  exact(over.taxableBenefitPool, 15000, "over excess");
  exact(over.taxableIncome, 315000, "over annual taxable");
  exact(over.taxDue, 9750, "over annual BIR column 2");
});


/** Read the persisted real-engine calculation trace, not a duplicate helper. */
function traceNumber(entry: { trace: unknown }, key: string): number {
  const inputs = (entry.trace as { inputs?: unknown } | null)?.inputs;
  const raw = Array.isArray(inputs)
    ? inputs.find((item) => typeof item === "string" && item.startsWith(key + "="))
    : undefined;
  return typeof raw === "string" ? Number(raw.slice(key.length + 1)) : Number.NaN;
}

function disposableCiDatabase(): boolean {
  // Even a developer's regular local/Neon DATABASE_URL MUST NOT be accessed.
  return process.env.CI === "true"
    && /^postgresql:\/\/postgres:postgres@127\.0\.0\.1:5432\/app_db(?:\?.*)?$/.test(process.env.DATABASE_URL ?? "")
    && process.env.DEMO_MODE === "false";
}

test("fixture selects a real supported 2026 national-holiday rule pack (not a 2025 bypass)", () => {
  const national = nationalHolidayCalendarForDate(ENGINE_PERIOD.periodEnd);
  assert.ok(national.length > 0, "A certified national holiday calendar must be present");
  assert.equal(national.filter((row) => row.date >= ENGINE_PERIOD.periodStart && row.date <= ENGINE_PERIOD.periodEnd).length, 0,
    "July 1-15, 2026 must remain a holiday-free national fixture; reselect if official coverage changes");
});

